ALTER TABLE test_assignments ADD COLUMN "assessorIds" TEXT[] NOT NULL DEFAULT '{}';
ALTER TABLE test_attempts ADD COLUMN "leftAt" TIMESTAMP(3), ADD COLUMN departures INTEGER NOT NULL DEFAULT 0, ADD COLUMN "awayMs" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "extraSeconds" INTEGER NOT NULL DEFAULT 0, ADD COLUMN "manuallySubmittedAt" TIMESTAMP(3);
ALTER TABLE user_answers ADD COLUMN "answeredAt" TIMESTAMP(3), ADD COLUMN "receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, ADD COLUMN delayed BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE expert_observations ADD COLUMN "indicatorExamples" JSONB NOT NULL DEFAULT '{}';
ALTER TABLE generated_reports ADD COLUMN "assessmentCompletedAt" TIMESTAMP(3), ADD COLUMN "readyAt" TIMESTAMP(3), ADD COLUMN "generationMode" TEXT NOT NULL DEFAULT 'ai';
CREATE TABLE report_artifacts ("reportId" TEXT PRIMARY KEY REFERENCES generated_reports(id) ON DELETE CASCADE, bytes BYTEA NOT NULL, sha256 TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE competency_models (id TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,version INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'draft',content JSONB NOT NULL,"authorId" TEXT NOT NULL,"approvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("organizationId",version));
CREATE INDEX competency_models_org ON competency_models("organizationId");
CREATE TABLE competency_consensus (id TEXT PRIMARY KEY,"organizationId" TEXT NOT NULL,"campaignId" TEXT NOT NULL,"membershipId" TEXT NOT NULL,"modelId" TEXT NOT NULL REFERENCES competency_models(id),version INTEGER NOT NULL,scores JSONB NOT NULL,"authorId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY ("campaignId","organizationId") REFERENCES campaigns(id,"organizationId") ON DELETE CASCADE,FOREIGN KEY ("membershipId","organizationId") REFERENCES memberships(id,"organizationId") ON DELETE CASCADE,UNIQUE("organizationId","campaignId","membershipId",version));
UPDATE test_versions SET "timeLimitSeconds"=CASE "testId" WHEN 'personality' THEN 1500 WHEN 'motivation' THEN 720 ELSE "timeLimitSeconds" END WHERE version='2.0-2026-10-26';
UPDATE test_attempts a SET "expiresAt"=a."timerStartedAt"+make_interval(secs=>v."timeLimitSeconds"+a."extraSeconds"),"pausedAt"=NULL FROM test_versions v,test_assignments t WHERE a."assignmentId"=t.id AND t."testVersionId"=v.id AND a.status='in_progress' AND a."timerStartedAt" IS NOT NULL AND v."timeLimitSeconds" IS NOT NULL;
UPDATE test_attempts SET "manuallySubmittedAt"="submittedAt" WHERE status='completed' AND ("expiresAt" IS NULL OR "submittedAt"<"expiresAt");
